import{_ as o,C as s,o as r,c as l,a2 as a,E as n}from"./chunks/framework.BSaF8iZ6.js";const y=JSON.parse('{"title":"Choosing a Plan","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/choosing-a-plan.md","filePath":"subscriptions/choosing-a-plan.md","lastUpdated":1789411447000}'),i={name:"subscriptions/choosing-a-plan.md"};function d(h,t,p,u,c,g){const e=s("ImagePopup");return r(),l("div",null,[t[0]||(t[0]=a('<h1 id="choosing-a-plan" tabindex="-1">Choosing a Plan <a class="header-anchor" href="#choosing-a-plan" aria-label="Permalink to &quot;Choosing a Plan&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>When the store uses subscription plans, each seller needs an active plan to sell. A plan sets how many products and team members you can have, the commission the store takes, and which parts of the Seller Panel you can use.</p><div class="warning custom-block"><p class="custom-block-title">Without an active plan</p><ul><li>You can only open <strong>My Profile</strong> and <strong>Plans</strong> in the Seller Panel.</li><li>Your team members can&#39;t open anything in the Seller Panel.</li><li>Your products aren&#39;t shown to customers.</li></ul></div><p>While the store uses plans, every seller lands on <strong>My Profile</strong> after signing in.</p><h2 id="see-the-available-plans" tabindex="-1">See the available plans <a class="header-anchor" href="#see-the-available-plans" aria-label="Permalink to &quot;See the available plans&quot;">​</a></h2><p>Go to <strong>Plans &gt;&gt; Available Plans</strong>.</p>',7)),n(e,{src:"/images/choosing-a-plan/available-plans.png",alt:"The Plans page with the available plans"}),t[1]||(t[1]=a('<p>If you have a plan, the page starts with <strong>Current Plan</strong>. Each plan card shows:</p><ul><li>the plan&#39;s name, with a star when the store recommends it;</li><li>its price and how many days it lasts;</li><li><strong>Max Products</strong>, <strong>Max Staff Ids</strong> and <strong>Admin Commission</strong>;</li><li>under <strong>Permissions</strong>, every part of the Seller Panel. Parts the plan doesn&#39;t include are shown in red with a cross.</li></ul><h2 id="buy-a-plan" tabindex="-1">Buy a plan <a class="header-anchor" href="#buy-a-plan" aria-label="Permalink to &quot;Buy a plan&quot;">​</a></h2><ol><li>Go to <strong>Plans &gt;&gt; Available Plans</strong>.</li><li>Click a plan. Its details open, with the description, the product types you can sell and the full list of permissions.</li><li>Click <strong>terms and conditions</strong> to read the store&#39;s terms.</li><li>Tick <strong>I have read and agree with terms and conditions.</strong></li><li>Click <strong>Proceed</strong>.</li><li>For a paid plan, choose a payment method and complete the payment.</li></ol>',4)),n(e,{src:"/images/choosing-a-plan/plan-details.png",alt:"The details of a plan with the terms checkbox"}),t[2]||(t[2]=a('<p>What happens next depends on the plan and how you pay:</p><table tabindex="0"><thead><tr><th>Plan or payment</th><th>Result</th></tr></thead><tbody><tr><td>A free plan</td><td>It is active straight away. The free plan is offered only until you have had a plan that became active.</td></tr><tr><td>PayPal</td><td>The plan is active once the payment goes through.</td></tr><tr><td>Another payment method, such as Money Transfer</td><td>The plan stays <strong>Pending</strong> until the store admin approves it. Cash On Delivery isn&#39;t offered for plans.</td></tr></tbody></table><p>When you already have a plan:</p><ul><li>Buying a plan while you&#39;re on the free plan ends the free plan straight away.</li><li>Buying a plan cancels any plan of yours that is still <strong>Pending</strong>.</li><li>Otherwise, the new plan starts when your current plan ends. You can&#39;t switch paid plans part-way through.</li></ul><p>If you leave the free plan and pay offline, you have no active plan until the admin approves the new one.</p><h2 id="your-plan-history" tabindex="-1">Your plan history <a class="header-anchor" href="#your-plan-history" aria-label="Permalink to &quot;Your plan history&quot;">​</a></h2><p>Go to <strong>Plans &gt;&gt; History</strong> to see every plan you have had, with its <strong>Status</strong> (<strong>Active</strong>, <strong>Pending</strong>, <strong>Expired</strong> or <strong>Canceled</strong>), start and end dates, payment method and price.</p>',7)),n(e,{src:"/images/choosing-a-plan/plan-history.png",alt:"The Plan History page"}),t[3]||(t[3]=a('<h2 id="what-your-plan-controls" tabindex="-1">What your plan controls <a class="header-anchor" href="#what-your-plan-controls" aria-label="Permalink to &quot;What your plan controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan detail</th><th>What it means for you</th></tr></thead><tbody><tr><td><strong>Max Products</strong></td><td>How many products you can list. At the limit, creating a product or a bulk upload shows <strong>You have reached max limit of … products.</strong>, and the admin can&#39;t approve products past it.</td></tr><tr><td><strong>Max Staff Ids</strong></td><td>How many team members you can add. See <a href="./../seller-panel/users-and-roles">Users &amp; Roles</a>.</td></tr><tr><td><strong>Admin Commission</strong></td><td>The commission the store takes from your sales while the plan is active.</td></tr><tr><td><strong>Product Types</strong></td><td>The kinds of product you can create and sell.</td></tr><tr><td><strong>Permissions</strong></td><td>The menus you and your team can use.</td></tr></tbody></table><h2 id="when-your-plan-ends" tabindex="-1">When your plan ends <a class="header-anchor" href="#when-your-plan-ends" aria-label="Permalink to &quot;When your plan ends&quot;">​</a></h2><ul><li>You receive reminder emails 9, 7, 3 and 1 days before your plan ends, and on desktop screens the Seller Panel header shows <strong>Subscription expires in:</strong> with a countdown for the last nine days. Both stop once your next plan is active. Buy your next plan before then to keep selling.</li><li>When a plan ends without another one to follow, you are back to <strong>My Profile</strong> and <strong>Plans</strong> only, and your products are hidden from customers.</li><li>If a new plan allows fewer products than you have, the products over the limit are switched off and need the admin&#39;s approval again.</li></ul><h2 id="plan-emails" tabindex="-1">Plan emails <a class="header-anchor" href="#plan-emails" aria-label="Permalink to &quot;Plan emails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Email</th><th>When</th></tr></thead><tbody><tr><td><strong>Subscription Created</strong></td><td>You buy a plan</td></tr><tr><td><strong>Subscription Activated</strong></td><td>Your plan becomes active</td></tr><tr><td><strong>Subscription Cancelled</strong></td><td>The admin cancels your plan, or you cancel a PayPal payment</td></tr><tr><td><strong>Subscription Expired</strong></td><td>Your plan ends</td></tr><tr><td><strong>Subscription expires in … day(s)</strong></td><td>9, 7, 3 and 1 days before your plan ends</td></tr></tbody></table><p>No email is sent when a plan is cancelled because you bought another plan, or because the admin deleted the plan.</p><p>For how the admin sets up plans, see <a href="./seller-subscription-management">Plans &amp; Subscriptions</a>.</p>',8))])}const b=o(i,[["render",d]]);export{y as __pageData,b as default};
